def check_suffix(s1, s2):
	l1 = len(s1)
	l2 = len(s2)
	if l1 >= l2:
		return 0
	if s2[-l1:] == s1:
		return 1
	return 0

def no_suffix(ls):
	ls2 = []
	for i in range(len(ls)):
		for j in range(len(ls)):
			if i == j:
				continue
			if check_suffix(ls[i], ls[j]) == 1:
				ls2.append(ls[i])
	for i in ls2:
		if i in ls:
			ls.remove(i)
	return ls
